En el componente cliente:

```tsx
"use client";

import { gsap } from "gsap";
import { useGSAP } from "@gsap/react";
import { ScrollTrigger } from "gsap/dist/ScrollTrigger";

if (typeof window !== "undefined") {
  gsap.registerPlugin(useGSAP, ScrollTrigger);
}
```

En Next.js, `"use client"` no impide que el módulo sea evaluado durante el build o SSR. Por eso `ScrollTrigger` se importa desde `gsap/dist/ScrollTrigger` y el registro queda protegido por la comprobación de `window`.
